<script setup lang="ts">
defineProps<{ content: Record<string, any> | null }>()
const nodeText = (node: any) => (node.content || []).map((item: any) => item.text || '').join('')
</script>
<template><div v-if="content?.content" class="rich-reader"><template v-for="(node, index) in content.content" :key="index"><h2 v-if="node.type === 'heading'" :class="`reader-heading reader-heading-${node.attrs?.level || 2}`">{{ nodeText(node) }}</h2><p v-else-if="node.type === 'paragraph'" class="reader-paragraph"><template v-for="(item, itemIndex) in node.content || []" :key="itemIndex"><code v-if="item.marks?.some((mark: any) => mark.type === 'code')">{{ item.text }}</code><strong v-else-if="item.marks?.some((mark: any) => mark.type === 'bold')">{{ item.text }}</strong><em v-else-if="item.marks?.some((mark: any) => mark.type === 'italic')">{{ item.text }}</em><span v-else>{{ item.text }}</span></template></p><CodePlayground v-else-if="node.type === 'courseCodeBlock'" :code="nodeText(node)" :filename="`${node.attrs?.language || 'javascript'}.js`" /><img v-else-if="node.type === 'image'" class="reader-image" :src="node.attrs?.src" :alt="node.attrs?.alt || 'Course image'"><ul v-else-if="node.type === 'bulletList'" class="reader-list"><li v-for="item in node.content || []" :key="item">{{ nodeText(item) }}</li></ul><ol v-else-if="node.type === 'orderedList'" class="reader-list"><li v-for="item in node.content || []" :key="item">{{ nodeText(item) }}</li></ol><blockquote v-else-if="node.type === 'blockquote'" class="reader-quote">{{ nodeText(node) }}</blockquote><hr v-else-if="node.type === 'horizontalRule'" class="reader-divider"><pre v-else-if="node.type === 'codeBlock'" class="reader-code"><code>{{ nodeText(node) }}</code></pre></template></div></template>
